/** Actual native whole-day preparation, readiness, worker claims and send permits. Model transport is explicitly fictional. */
class CatalogDayAnalysisDispatchTest {
    boolean mysql(){return false;}
    CatalogDayAnalysisDispatchPermitTest helper(){return new CatalogDayAnalysisDispatchPermitTest(){@Override boolean mysql(){return CatalogDayAnalysisDispatchTest.this.mysql();}};}
    record Built(CatalogDayAnalysisDispatchPermitTest.Built data,DispatchReadinessService readiness,VersionValidityLedgerService validity,WorkerAuthorizationService worker,Clock clock){ }
    Built fixture(String category,boolean alias){var helper=helper();var built=helper.fixture(category,alias);var data=built.data().data();var f=data.f().f;
        columns(f.source,f.jdbc,"source_run_items","validity_revision BIGINT DEFAULT 0","effective_valid INT DEFAULT 1");columns(f.source,f.jdbc,"jobs","validity_revision BIGINT","reverses_disposition_id VARCHAR(64)");
        Clock clock=Clock.fixed(data.outer().completed.plusSeconds(180),ZoneOffset.UTC);var generated=new GeneratedContentService(new JdbcGeneratedContents(f.source),clock);
        var ledger=new VersionValidityLedgerService(new JdbcVersionValidity(f.source),new FrozenContentVersionService(new JdbcFrozenContentVersions(f.source)),new EvidenceValidityService(new JdbcEvidenceValidity(f.source)),new ContentReviewWriteService(new JdbcReviewPublication(f.source),generated,clock),clock,"fictional-owner");
        var routes=new HashMap<String,CatalogDayAnalysisDispatchPermitService>();for(String value:List.of("agent","skill","workflow","model"))routes.put(value,value.equals(category)?helper.provider(built):mock(CatalogDayAnalysisDispatchPermitService.class));
        var inputs=new JdbcFrozenInputs(f.source);var readiness=new DispatchReadinessService(new JdbcDispatchInputs(f.source),inputs,new FrozenDependencyIndexService(inputs,new JdbcFrozenDependencies(f.source)),new GenerationLineageService(new JdbcGenerationLineage(f.source),clock,"analysis-worker"),new ContentReadService(new JdbcContentReads(f.source),f.tx,ContentReadService.denyUnverifiedReferences()),new SourceMemberEvidenceService(new JdbcSourceMemberEvidence(f.source)),target->ledger.exactVersionExists(target)&&ledger.validity(target).effectiveValid(),null,null,false,null,null,f.tx,null,routes);
        var worker=new WorkerAuthorizationService(f.writes,new WorkerJdbcStore(new JdbcWorkerState(f.source),new JdbcJobRecords(f.source),"fictional-analysis-epoch",()->false,readiness,clock,f.tx),clock,()->true);return new Built(built,readiness,ledger,worker,clock);
    }
    static void columns(DataSource source,org.springframework.jdbc.core.JdbcTemplate jdbc,String table,String... declarations){try(var connection=source.getConnection();var rows=connection.getMetaData().getColumns(connection.getCatalog(),null,connection.getMetaData().getDatabaseProductName().equals("H2")?table.toUpperCase(Locale.ROOT):table,null)){var existing=new HashSet<String>();while(rows.next())existing.add(rows.getString("COLUMN_NAME").toLowerCase(Locale.ROOT));for(String declaration:declarations)if(!existing.contains(declaration.split(" ")[0]))jdbc.execute("ALTER TABLE "+table+" ADD "+declaration);}catch(java.sql.SQLException failure){throw new RuntimeException(failure);}}
    SharedWriteExecutor.ActionContext action(String suffix){return new SharedWriteExecutor.ActionContext("fictional-catalog-analysis-"+suffix,"fictional-analysis-action",null);}
    @Test void FourCategoriesActualReadinessWorkerClaimAndSendUseOnlyTheOriginalRequest(){for(String category:List.of("agent","skill","workflow","model")){var built=fixture(category,false);var data=built.data().data().data();var input=built.data().input();var proof=built.readiness().captureSource(input.ownerId());assertTrue(data.f().write(()->built.readiness().readyCaptured(input.ownerId(),proof)));assertThrows(RuntimeException.class,()->data.f().write(()->built.readiness().ready(input.ownerId())));var claim=built.worker().claim(action("claim"));assertEquals(WorkerAuthorizationService.State.CLAIMED,claim.state());assertEquals(input.ownerId(),claim.permit().identity().rootId());var sent=built.worker().dispatch(claim.permit(),request->{assertEquals(input.requestJson(),JdbcFrozenInputs.canonical(CanonicalJson.parse(request)));data.f().f.sends++;return "fictional analysis response";});assertEquals(WorkerAuthorizationService.State.SENT,sent.state());assertEquals(1,data.f().f.jdbc.queryForObject("SELECT call_count FROM jobs WHERE id=?",Integer.class,input.ownerId()));assertEquals(3,data.f().f.sends);}}
    @Test void ActualAliasVersionTwoSendPreservesBothBodiesAndOriginalPreviousLineage(){var built=fixture("agent",true);var data=built.data().data().data();var input=built.data().input();var claim=built.worker().claim(action("version-claim"));assertEquals(WorkerAuthorizationService.State.CLAIMED,claim.state());assertEquals(2,data.f().f.jdbc.queryForObject("SELECT generation FROM jobs WHERE id=?",Integer.class,claim.permit().identity().rootId()));assertEquals(2,CanonicalJson.parse(input.snapshotJson()).get("members").size());assertEquals(WorkerAuthorizationService.State.SENT,built.worker().dispatch(claim.permit(),request->{assertEquals(input.requestJson(),JdbcFrozenInputs.canonical(CanonicalJson.parse(request)));return "fictional alias analysis response";}).state());assertEquals(CatalogPreviousAnalysisTest.Fixture.ROOT,data.f().f.jdbc.queryForObject("SELECT supersedes_job_id FROM jobs WHERE id=?",String.class,input.ownerId()));assertEquals(2,data.f().f.sends);}
    @Test void ActualNativeReferenceInvalidationBetweenClaimAndSendPreventsTransport(){var built=fixture("skill",false);var data=built.data().data().data();var input=built.data().input();var claim=built.worker().claim(action("invalid-reference-claim"));assertEquals(WorkerAuthorizationService.State.CLAIMED,claim.state());var target=CanonicalJson.parse(input.snapshotJson()).get(FrozenApplicationContext.FIELD).get("reference_targets").get(0);var command=new VersionValidityService.Command(target,0,VersionValidityService.Action.INVALIDATE,"Fictional source invalidation",null);data.f().write(()->{String key=JdbcFrozenInputs.canonical(target),hash=VersionValidityService.commandHash(command,key);built.validity().lockStableIdentity(target);built.validity().append(command,hash,1,"fictional-analysis-reference-invalidated");return true;});var calls=new java.util.concurrent.atomic.AtomicInteger();assertNotEquals(WorkerAuthorizationService.State.SENT,built.worker().dispatch(claim.permit(),request->{calls.incrementAndGet();return "fictional forbidden response";}).state());assertEquals(0,calls.get());assertEquals(2,data.f().f.sends);}
    @Test void CurrentGenerationChangesBetweenClaimAndAuthorizationPreventTransport(){var built=fixture("workflow",false);var data=built.data().data().data();var claim=built.worker().claim(action("changed-generation-claim"));assertEquals(WorkerAuthorizationService.State.CLAIMED,claim.state());data.f().f.jdbc.update("UPDATE analyzed_entities SET analysis_generation=analysis_generation+1");var calls=new java.util.concurrent.atomic.AtomicInteger();assertNotEquals(WorkerAuthorizationService.State.SENT,built.worker().dispatch(claim.permit(),request->{calls.incrementAndGet();return "fictional forbidden response";}).state());assertEquals(0,calls.get());assertEquals(2,data.f().f.sends);}
    @Test void DamagedOrOversizedOriginalRequestIsRejectedBeforeSendAndWithoutLoadingWideAttemptPayload(){var built=fixture("model",false);var data=built.data().data().data();var root=built.data().input().ownerId();var proof=built.readiness().captureSource(root);assertThrows(RuntimeException.class,()->data.f().write(()->{data.f().f.jdbc.update("UPDATE jobs SET request_json='{}' WHERE id=?",JdbcFrozenInputs.stableId("attempt",root+":1"));return built.readiness().readyCaptured(root,proof);}));var wide=tools.jackson.databind.json.JsonMapper.shared().createObjectNode().put("fictional","x".repeat(1048576));assertThrows(RuntimeException.class,()->data.f().write(()->{data.f().f.jdbc.update("UPDATE jobs SET request_json=? WHERE id=?",JdbcFrozenInputs.canonical(wide),JdbcFrozenInputs.stableId("attempt",root+":1"));return built.readiness().readyCaptured(root,proof);}));assertTrue(data.f().write(()->built.readiness().readyCaptured(root,proof)));assertEquals(0,data.f().f.jdbc.queryForObject("SELECT call_count FROM jobs WHERE id=?",Integer.class,root));assertEquals(2,data.f().f.sends);}
    @Test void ExplicitWholeCatalogRoutesAreMandatoryForNewProfileAndClosedAtConstruction(){var built=fixture("agent",false);var data=built.data().data().data();var f=data.f().f;var inputs=new JdbcFrozenInputs(f.source);var roots=new JdbcDispatchInputs(f.source);var deps=new FrozenDependencyIndexService(inputs,new JdbcFrozenDependencies(f.source));var lineage=new GenerationLineageService(new JdbcGenerationLineage(f.source),built.clock(),"analysis-worker");var content=new ContentReadService(new JdbcContentReads(f.source),f.tx,ContentReadService.denyUnverifiedReferences());var members=new SourceMemberEvidenceService(new JdbcSourceMemberEvidence(f.source));var legacy=new DispatchReadinessService(roots,inputs,deps,lineage,content,members,target->true,null,null,false,null,null,f.tx,null);assertThrows(RuntimeException.class,()->legacy.captureSource(built.data().input().ownerId()));assertThrows(RuntimeException.class,()->new DispatchReadinessService(roots,inputs,deps,lineage,content,members,target->true,null,null,false,null,null,f.tx,null,Map.of("agent",helper().provider(built.data()))));var p=mock(CatalogDayAnalysisDispatchPermitService.class);var tx=mock(PlatformTransactionManager.class);var r=mock(JdbcDispatchInputs.class);var i=mock(JdbcFrozenInputs.class);var d=mock(FrozenDependencyIndexService.class);var l=mock(GenerationLineageService.class);var c=mock(ContentReadService.class);var m=mock(SourceMemberEvidenceService.class);var ref=mock(ResultJdbcStore.ReferenceProof.class);assertNotNull(new DispatchReadinessService(r,i,d,l,c,m,ref,null,null,false,null,null,tx,null,Map.of("agent",p,"skill",p,"workflow",p,"model",p)));verifyNoInteractions(p,tx,r,i,d,l,c,m,ref);}
}
